const int g_num_imports = sizeof(g_imports) / sizeof(g_imports[0]);

uintptr_t imports_lookup(const char *name) {
  for (int i = 0; i < g_num_imports; i++)
    if (!strcmp(g_imports[i].symbol, name)) return g_imports[i].func;
  return 0;
}
